css:
@media print {
    @page {
        @bottom-right {
            content: "Page " counter(page) " of " counter(pages);
        }
    }
}

@media print {
    .nowrap-print {
        white-space: nowrap;
    }
}

 .print-format {

        margin-left: 2mm!important;
        margin-right: 2mm!important;
    }

/* Browser print: a zero page margin makes Chrome drop its own date/title/URL header and footer.
   The spacing is kept with padding on the print format instead. */
@media print {
    @page {
        margin: 0;
    }
    .print-format {
        padding: 8mm 4mm !important;
    }
}
